 -->\n      <g transform='translate(0, 10)'>\n        <path d='M 50,0 Q 80,40 50,110 Q 20,40 50,0 Z' fill='#f97316' opacity='0.8' stroke='#ea580c' stroke-width='2'/>\n        <text x='50' y='130' text-anchor='middle' fill='#0f172a' font-size='11' font-weight='bold'>Storage Taproot</text>\n        <text x='50' y='145' text-anchor='middle' fill='#64748b' font-size='10'>(Carrot, Turnip)</text>\n      </g>\n      \n      <!-- Prop / Stilt Roots -->\n      <g transform='translate(130, 10)'>\n        <line x1='20' y1='10' x2='80' y2='10' stroke='#78350f' stroke-width='6'/>\n        <line x1='35' y1='10' x2='25' y2='110' stroke='#b45309' stroke-width='3'/>\n        <line x1='65' y1='10' x2='75' y2='110' stroke='#b45309' stroke-width='3'/>\n        <text x='50' y='130' text-anchor='middle' fill='#0f172a' font-size='11' font-weight='bold'>Prop / Stilt Roots</text>\n        <text x='50' y='145' text-anchor='middle' fill='#64748b' font-size='10'>(Banyan, Maize)</text>\n      </g>\n      \n      <!-- Pneumatophores -->\n      <g transform='translate(260, 10)'>\n        <line x1='10' y1='110' x2='110' y2='110' stroke='#475569' stroke-width='4'/>\n        <line x1='35' y1='110' x2='35' y2='20' stroke='#16a34a' stroke-width='4'/>\n        <line x1='65' y1='110' x2='65' y2='30' stroke='#16a34a' stroke-width='4'/>\n        <line x1='90' y1='110' x2='90' y2='15' stroke='#16a34a' stroke-width='4'/>\n        <text x='60' y='130' text-anchor='middle' fill='#0f172a' font-size='11' font-weight='bold'>Pneumatophores</text>\n        <text x='60' y='145' text-anchor='middle' fill='#64748b' font-size='10'>(Rhizophora - breathing)</text>\n      </g>\n    </g>\n  </g>\n</svg>"
